import json, os
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("weather")
PLACES = ["Leeds", "York"]


@mcp.tool()
def get_forecast(place: str) -> dict:
    """Today's forecast for a saved place."""
    if place not in PLACES:
        raise ValueError(f"{place} is not a saved place.")
    return {"today": "rain, 11°C"}


@mcp.tool()
def list_places() -> list:
    """The saved places."""
    return PLACES


if __name__ == "__main__":
    mcp.run()

